/* LückenSprint: offline, browser-only C-Test trainer */
const APP_VERSION='1.0.0', EXAM_SECONDS=40*60;
const TOPICS=[
 ['Alltag','guten Start in den Tag','kleine Aufgaben in Ruhe zu planen','einen kurzen Weg durch die Stadt'],['Universität','einen Einführungskurs an der Universität','Materialien für das Seminar','mit anderen Studierenden über Ideen zu sprechen'],['Arbeit','den ersten Arbeitstag in einem neuen Team','eine praktische Lösung für eine Aufgabe','die Ergebnisse verständlich zu erklären'],['Wohnen','eine Wohnung in einem ruhigen Viertel','die gemeinsamen Räume ordentlich','mit den Nachbarn freundlich zu sprechen'],['Verkehr','den Weg mit Bus und Straßenbahn','eine passende Verbindung für den Morgen','bei Verspätungen geduldig zu bleiben'],['Gesundheit','gesunde Gewohnheiten im Alltag','genug Wasser und regelmäßige Pausen','auf die Signale des Körpers zu achten'],['Sport','eine Laufgruppe im Park','ein Training mit klaren kleinen Zielen','sich nach dem Sport besser zu fühlen'],['Reisen','eine Reise in eine unbekannte Stadt','einen leichten Koffer für mehrere Tage','neue Orte aufmerksam zu entdecken'],['Digitale Kommunikation','eine Nachricht an eine Lerngruppe','klare und höfliche Formulierungen','wichtige Informationen nicht zu übersehen'],['Künstliche Intelligenz','digitale Werkzeuge mit künstlicher Intelligenz','die Ergebnisse solcher Systeme kritisch','Technik verantwortungsvoll zu verwenden'],['Umwelt','einen Gemeinschaftsgarten im Viertel','Müll zu vermeiden und Ressourcen zu sparen','Veränderungen im Alltag gemeinsam umzusetzen'],['Bildung','einen offenen Lerntag in der Schule','unterschiedliche Wege zum Lernen','Fragen ohne Angst zu stellen'],['Wissenschaft','ein einfaches Experiment im Labor','Beobachtungen sorgfältig zu notieren','aus Daten vorsichtige Schlüsse zu ziehen'],['Technologie','eine neue App für den Alltag','nützliche Funktionen vor der Nutzung','digitale Angebote bewusst auszuwählen'],['Soziale Medien','eine Diskussion in sozialen Medien','Beiträge vor dem Teilen genau','respektvoll mit anderen Meinungen umzugehen'],['Politik','eine öffentliche Diskussion im Rathaus','verschiedene Vorschläge sachlich','Entscheidungen nachvollziehbar zu erklären'],['Wirtschaft','einen kleinen Markt am Samstag','Preise und Qualität zu vergleichen','lokale Angebote sinnvoll zu nutzen'],['Kultur','eine Ausstellung im Stadtmuseum','Geschichten hinter den Bildern','kulturelle Angebote neugierig zu besuchen'],['Geschichte','ein altes Gebäude am Fluss','Spuren aus früheren Zeiten','Vergangenheit und Gegenwart zu verbinden'],['Psychologie','die Wirkung von Pausen beim Lernen','Aufmerksamkeit über längere Zeit','eigene Lerngewohnheiten besser zu verstehen'],['Forschung','ein Projekt über städtische Luftqualität','Messungen an mehreren Orten','Forschungsergebnisse transparent zu prüfen'],['Energie','ein Haus mit Solaranlage','Strom auch bei hohem Verbrauch','Energie im Alltag weniger zu verschwenden'],['Datenschutz','persönliche Daten in einer Anwendung','Berechtigungen vor der Anmeldung','digitale Privatsphäre aktiv zu schützen'],['Stadtplanung','einen Platz ohne viel Autoverkehr','sichere Wege für Fahrräder und Fußgänger','öffentliche Räume für viele Menschen zu gestalten'],['Integration','ein Sprachcafé in der Bibliothek','Menschen mit unterschiedlichen Erfahrungen','gemeinsame Regeln im Alltag zu finden']
];
const TAGS={A1:['Präsens','Alltag','Wortschatz'],A2:['Perfekt','Modalverben','Zeitangaben'],B1:['weil / obwohl','Relativsätze','trennbare Verben'],B2:['Nominalisierung','Passiv','Konnektoren'],C1:['Argumentation','Partizipialattribute','Fachsprache']};
function makeText(level,t,i){const [topic,lead,object,action]=t; const title=topic+' · '+(i+1);let text='';
 if(level==='A1')text=`Heute beginnt ${lead}. Maria findet ${object} wichtig. Am Morgen spricht sie mit einer Freundin darüber. Danach macht sie einen Plan für den Tag. Sie nimmt sich genug Zeit und arbeitet Schritt für Schritt. In der Pause trinkt sie Wasser und schaut aus dem Fenster. Am Abend erzählt sie ihrer Familie von ihren Erfahrungen. Alle hören interessiert zu und geben ihr freundliche Tipps.`;
 if(level==='A2')text=`Seit einigen Wochen beschäftigt sich Amir mit ${lead}. Zuerst wollte er nur ${object} ausprobieren, doch bald merkte er, wie viel Freude ihm die Sache macht. Deshalb sucht er jeden Dienstag Informationen in der Bibliothek. Seine Schwester begleitet ihn manchmal, obwohl sie andere Interessen hat. Gemeinsam überlegen sie, wie sie ${action} können. Nach jedem Treffen schreibt Amir drei neue Wörter in sein Heft. So kann er später leichter über seine Erfahrungen sprechen.`;
 if(level==='B1')text=`In diesem Monat organisiert unsere Gruppe ${lead}. Zunächst dachten viele, dass ${object} zu schwierig wäre, weil nur wenig Zeit zur Verfügung stand. Trotzdem teilten wir die Aufgaben auf und vereinbarten feste Termine. Die Kollegin, die schon ähnliche Projekte begleitet hatte, erklärte uns einen wichtigen Ablauf. Einige Materialien wurden von der Verwaltung bereitgestellt, andere mussten wir selbst besorgen. Wenn ein Problem auftauchte, riefen wir einander sofort an. Am Ende merkten wir, dass wir ${action} gelernt hatten. Das Ergebnis machte alle Beteiligten stolz.`;
 if(level==='B2')text=`Die aktuelle Diskussion über ${lead} zeigt, dass ${object} nicht allein eine technische Frage ist. Eine nachhaltige Verbesserung kann nur erreicht werden, wenn unterschiedliche Interessen frühzeitig berücksichtigt werden. In einer Befragung wurde deutlich, dass viele Menschen ${action} möchten, zugleich jedoch verständliche Informationen erwarten. Die sorgfältige Auswertung der Rückmeldungen ermöglicht eine differenzierte Planung. Maßnahmen sollten nicht lediglich angekündigt, sondern transparent begründet und regelmäßig überprüft werden. Besonders hilfreich sind Kooperationen zwischen Fachleuten, Verwaltung und engagierten Bürgerinnen und Bürgern. Dadurch wird die Umsetzung weniger abhängig von einzelnen Entscheidungen. Langfristig entsteht so ein Angebot, dessen Nutzen auch außerhalb der ursprünglichen Zielgruppe wahrgenommen wird.`;
 if(level==='C1')text=`Die Auseinandersetzung mit ${lead} verdeutlicht exemplarisch, weshalb ${object} weder durch vereinfachende Schlagworte noch durch isolierte Einzelmaßnahmen angemessen beantwortet werden kann. Zwar wird häufig gefordert, möglichst schnell sichtbare Ergebnisse zu produzieren; diese Erwartung übersieht jedoch, dass tragfähige Veränderungen auf nachvollziehbaren Verfahren beruhen. Eine Untersuchung, deren Zwischenergebnisse öffentlich diskutiert wurden, legt nahe, dass viele Beteiligte ${action} befürworten, sofern Zuständigkeiten und mögliche Nebenfolgen transparent dargestellt werden. Entscheidend ist dabei nicht die bloße Bereitstellung von Informationen, sondern deren Einordnung in einen größeren Zusammenhang. Werden Erfahrungen verschiedener Gruppen systematisch berücksichtigt, lassen sich Zielkonflikte früher erkennen und produktiv bearbeiten. Die daraus entstehende Entscheidungskultur stärkt nicht nur die Akzeptanz konkreter Maßnahmen, sondern auch das Vertrauen in öffentliche Institutionen.`;
 text+=` Zusätzlich wird bei dieser Ausgabe ein besonderer Aspekt hervorgehoben: ${['die Vorbereitung im Team','die Rolle klarer Informationen','die Bedeutung kleiner Routinen','der Nutzen offener Fragen','die Verbindung von Theorie und Praxis'][i%5]}.`;return {id:`${level.toLowerCase()}-${String(i+1).padStart(2,'0')}`,title,level,topic,text,difficulty:{A1:1,A2:2,B1:3,B2:4,C1:5}[level],readingTime:{A1:1,A2:1,B1:2,B2:2,C1:3}[level],grammarTags:TAGS[level],vocabularyTags:[topic,'Kontext','Lückentext']};}
const LEVELS=['A1','A2','B1','B2','C1']; const COUNTS={A1:20,A2:25,B1:30,B2:30,C1:20};
let DB=typeof window==='undefined'?Object.fromEntries(LEVELS.map(level=>[level,Array.from({length:COUNTS[level]},(_,i)=>makeText(level,TOPICS[i%TOPICS.length],i))])):{};
let ALL=typeof window==='undefined'?LEVELS.flatMap(l=>DB[l]):[];
const DATA_FILES=LEVELS.map(level=>[level,`./data/texts-${level.toLowerCase()}.json`]),TEXT_CACHE_KEY='lueckenSprintTextDatabase-v1',TEXT_TIMEOUT_MS=6500;
function setDatabase(raw){const next=Object.fromEntries(LEVELS.map(level=>[level,raw[level]||raw[`texts-${level.toLowerCase()}`]||[]])),nextAll=LEVELS.flatMap(level=>next[level]);if(nextAll.length!==125||new Set(nextAll.map(t=>t.id)).size!==125)throw new Error('Metin veritabanı doğrulanamadı.');DB=next;ALL=nextAll;}
function restoreCachedDatabase(){if(typeof window==='undefined'||window.__STANDALONE_TEXTS__)return false;try{setDatabase(JSON.parse(localStorage.getItem(TEXT_CACHE_KEY)||'null'));return true}catch{return false}}
function cacheDatabase(raw){try{localStorage.setItem(TEXT_CACHE_KEY,JSON.stringify(raw))}catch{}}
function setTextRefreshIndicator(active){const old=document.querySelector('#textRefreshIndicator');if(!active){old?.remove();return}const el=old||document.body.appendChild(Object.assign(document.createElement('div'),{id:'textRefreshIndicator',className:'text-refresh-indicator',role:'status'}));el.textContent='Metinler arka planda güncelleniyor…'}
async function loadDatabase(){if(typeof window==='undefined')return;if(window.__STANDALONE_TEXTS__){setDatabase(window.__STANDALONE_TEXTS__);return}const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),TEXT_TIMEOUT_MS);try{const entries=await Promise.all(DATA_FILES.map(async([level,file])=>{const response=await fetch(file,{signal:controller.signal});if(!response.ok)throw new Error(`${file} yüklenemedi.`);return[level,await response.json()]})),raw=Object.fromEntries(entries);setDatabase(raw);cacheDatabase(raw)}finally{clearTimeout(timeout)}}
function refreshTextDatabaseInBackground(){if(window.__TEXT_REFRESHING__||window.__STANDALONE__)return;window.__TEXT_REFRESHING__=true;setTextRefreshIndicator(true);loadDatabase().catch(()=>{}).finally(()=>{window.__TEXT_REFRESHING__=false;setTextRefreshIndicator(false)})}
const DEFAULT={version:APP_VERSION,settings:{theme:'system',lenient:true,acceptSS:true,hint:false,shortWords:false,gaps:20,timer:true,font:16,dailyTarget:40,autoNext:true,instantSave:true,confirmExam:true,bands:[60,70,80,90]},attempts:[],errors:[],custom:[],daily:{},tasks:{},activeExam:null,seen:[]};
function clone(v){return JSON.parse(JSON.stringify(v))} function load(){try{return {...clone(DEFAULT),...JSON.parse(localStorage.getItem('lueckenSprint')||'{}'),settings:{...DEFAULT.settings,...(JSON.parse(localStorage.getItem('lueckenSprint')||'{}').settings||{})}}}catch{return clone(DEFAULT)}}let S=load();
function save(){S.sync_meta={...(S.sync_meta||{}),updated_at:new Date().toISOString()};localStorage.setItem('lueckenSprint',JSON.stringify(S));applyTheme();window.LueckenSync?.onLocalSave?.()}
function uid(){return `${Date.now()}-${Math.random().toString(36).slice(2,7)}`} function esc(x=''){return String(x).replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]))}
function norm(s,options={}){let r=String(s).trim();if(options.lenient)r=r.toLocaleLowerCase('de-DE');if(options.acceptSS)r=r.replace(/ß/g,'ss');return r}
function firstSentenceEnd(text){const m=text.match(/^.*?[.!?](?=\s|$)/u);return m?m[0].length:0}
function ctest(text,{gaps=20,every=2,shortWords=false,hint=false}={}){const start=firstSentenceEnd(text);const head=text.slice(0,start),tail=text.slice(start);const token=/https?:\/\/\S+|www\.\S+|\b(?:[A-Za-zÄÖÜäöüß]\.){2,}|\b\d+(?:[.,]\d+)?\b|[A-Za-zÄÖÜäöüß]+(?:-[A-Za-zÄÖÜäöüß]+)*/gu;let last=0,eligible=0,used=0,html=esc(head),items=[],m;
 while((m=token.exec(tail))){html+=esc(tail.slice(last,m.index));const word=m[0],pure=/^[A-Za-zÄÖÜäöüß]+$/u.test(word); const ok=pure&&(shortWords?word.length>=3:word.length>=4);if(ok)eligible++;if(ok&&eligible%every===0&&used<gaps){const cut=Math.floor(word.length/2),prefix=word.slice(0,cut),missing=word.slice(cut),id=`gap-${used}`;html+=`<span class="word-gap">${esc(prefix)}<input aria-label="${esc(prefix)} ile başlayan kelime" placeholder="${hint?esc(missing[0]):''}" class="gap" style="--gap-ch:${missing.length}" id="${id}" data-gap="${used}" data-word="${esc(word)}" data-prefix="${esc(prefix)}" autocomplete="off" autocapitalize="none" spellcheck="false"></span><span class="punct"></span>`;items.push({id,word,prefix,missing,index:m.index});used++}else html+=esc(word);last=m.index+word.length}
 html+=esc(tail.slice(last));return {html,items,gapCount:items.length,head};}
function score(items,answers,opts){let correct=0,unanswered=0;const details=items.map((it,i)=>{const answer=(answers[i]||'').trim(),ok=norm(answer,opts)===norm(it.missing,opts);if(ok)correct++;if(!answer)unanswered++;return {...it,answer,correct:ok}});return {correct,incorrect:items.length-correct-unanswered,unanswered,total:items.length,percent:items.length?Math.round(correct/items.length*100):0,details}}
function category(item){const w=item.word.toLowerCase(),a=item.answer.toLowerCase();if(w.includes('ß')&&a.includes('ss'))return 'ß versus ss';if(/[äöü]/.test(w)&&!/[äöü]/.test(a))return'Umlaut';if(item.word[0]!==item.word[0].toLowerCase())return'Büyük harf';if(/(ung|heit|keit|schaft|tion)$/u.test(w))return'İsim eki';if(/(en|ern|est|et|te)$/u.test(w))return'Fiil çekimi';if(/(ig|lich|isch|bar)$/u.test(w))return'Sıfat eki';if(/(weil|obwohl|deshalb|damit|jedoch)$/u.test(w))return'Bağlaç';if(w.includes('-'))return'Birleşik kelime';return'Sözcük yazımı'}
function today(){return new Date().toISOString().slice(0,10)} function dayDiff(date){return Math.max(0,Math.ceil((new Date(`${date}T00:00:00`)-new Date())/86400000))}
function findText(id){return ALL.concat(S.custom||[]).find(t=>t.id===id)} function choose(level,topic,offset=0){let a=level==='mixed'?ALL:DB[level]||ALL;if(topic&&topic!=='all')a=a.filter(x=>x.topic===topic);if(!a.length)a=ALL;const unseen=a.filter(x=>!S.seen.includes(x.id));return (unseen.length?unseen:a)[(Date.now()+offset)% (unseen.length?unseen.length:a.length)]}
function formatDate(d){return new Intl.DateTimeFormat('tr-TR',{day:'numeric',month:'long',year:'numeric'}).format(new Date(`${d}T12:00:00`))}
function phase(){const d=today();if(d<='2026-08-07')return ['1. Faz · Biçimi öğren','29 Temmuz – 7 Ağustos','Bugün iki kısa metin çöz; ekleri ve bağlamı sakince yeniden kur.'];if(d<='2026-08-17')return['2. Faz · Zamanlı metinler','8 – 17 Ağustos','A2, B1 ve B2 karışımı çöz; metin başına yaklaşık 6–7 dakika hedefle.'];if(d<='2026-08-28')return['3. Faz · Yoğun karışık pratik','18 – 28 Ağustos','En az 60 boşluk çöz ve zayıf kategorileri tekrar et.'];if(d<='2026-09-04')return['4. Faz · Tam denemeler','29 Ağustos – 4 Eylül','Bugün tam deneme ya da hata tekrarına odaklan.'];return['5. Faz · Hafif tekrar','5 – 6 Eylül','Kısa bir karışık test çöz; yorucu bir çalışma yapma.']}
function attemptStats(){const a=S.attempts,tot=a.reduce((x,y)=>x+y.total,0),ok=a.reduce((x,y)=>x+y.correct,0),ex=a.filter(x=>x.mode==='exam');return {exercises:a.filter(x=>x.mode!=='exam').length,exams:ex.length,gaps:tot,accuracy:tot?Math.round(ok/tot*100):0,best:ex.length?Math.max(...ex.map(x=>x.percent)):0}}
function toast(message){const t=document.querySelector('#toast');t.textContent=message;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2800)}
function modal(title,text,onOK,label='Onayla'){const m=document.querySelector('#modal');m.innerHTML=`<div class="modal"><h2>${esc(title)}</h2><p>${esc(text)}</p><div class="modal-actions"><button class="button-outline" id="modalNo">Vazgeç</button><button class="button" id="modalYes">${esc(label)}</button></div></div>`;m.classList.remove('hidden');m.querySelector('#modalNo').onclick=()=>m.classList.add('hidden');m.querySelector('#modalYes').onclick=()=>{m.classList.add('hidden');onOK()}}
function applyTheme(){const choice=S.settings.theme;document.body.classList.toggle('dark',choice==='dark'||(choice==='system'&&matchMedia('(prefers-color-scheme: dark)').matches));document.documentElement.style.fontSize=`${S.settings.font}px`}
function header(eyebrow,title,lead=''){return `<div class="eyebrow">${eyebrow}</div><h1 class="page-title">${title}</h1>${lead?`<p class="lead">${lead}</p>`:''}`}
function metric(label,value){return `<div class="card stat"><small>${label}</small><strong>${value}</strong></div>`}
function renderHome(){const s=attemptStats(),p=phase(),last=S.attempts.slice(-5).reverse(),dailyGaps=S.attempts.filter(x=>x.date===today()).reduce((n,x)=>n+x.total,0);return `${header('FAU yerleştirme hazırlığı','Her boşluğu bir ipucu gibi kullan.','C-Test performansını hedefleyen kişisel, çevrimdışı antrenör.')}
 <section class="hero"><div><div class="eyebrow">7 Eylül 2026 · sınav günü</div><h1>Hedef: C-Test sonucunda en az B1.2, tercihen B2.1 yerleştirmesi almak.</h1><p>Bu araç konuşma seviyeni ölçme iddiasında değildir; C-Test formatında hız, bağlam ve doğru yazım çalıştırır.</p><button class="button" data-go="practice">Hızlı pratik başlat</button></div><div class="countdown"><strong>${dayDiff('2026-09-07')}</strong><span>gün kaldı</span><div class="progressbar" style="margin-top:15px"><i style="width:${Math.min(100,Math.max(0,100-dayDiff('2026-09-07')/40*100))}%"></i></div></div></section>
 <div class="grid grid-3" style="margin-top:18px">${metric('Tamamlanan alıştırma',s.exercises)}${metric('Yanıtlanan boşluk',s.gaps)}${metric('Ortalama doğruluk',s.accuracy+'%')}${metric('Tam deneme',s.exams)}${metric('En iyi deneme',s.best?s.best+'%':'—')}${metric('Bugünün boşlukları',dailyGaps+'/'+S.settings.dailyTarget)}</div>
 <div class="section-heading"><h2>Bugünün planı</h2><span>${formatDate(today())}</span></div><section class="card phase"><h3>${p[0]}</h3><p><b>${p[1]}</b> · ${p[2]}</p><div style="margin-top:14px"><button class="button-outline" id="taskDone">${S.tasks[today()]?'✓ Bugün tamamlandı':'Bugünkü görevi tamamla'}</button></div></section>
 <div class="grid grid-2" style="margin-top:18px"><section class="card"><h3 style="margin-top:0">Son sonuçlar</h3>${last.length?`<div class="table-wrap"><table class="data-table"><tr><th>Tarih</th><th>Tür</th><th>Seviye</th><th>Sonuç</th></tr>${last.map(x=>`<tr><td>${x.date}</td><td>${x.mode==='exam'?'Deneme':'Pratik'}</td><td>${x.level}</td><td>${x.percent}%</td></tr>`).join('')}</table></div>`:'<p class="empty">İlk pratikten sonra sonuçların burada görünür.</p>'}</section><section class="card"><h3 style="margin-top:0">Günlük seri</h3><strong style="font-size:35px">${streak()} gün</strong><p class="lead" style="font-size:13px;margin:8px 0">Takvimde tamamlanan günler yeşil görünür. Her gün en az bir alıştırma yaparak seriyi koru.</p><button class="button-outline" data-go="daily">Günlük mücadeleye git</button></section></div>`}
function streak(){let n=0,d=new Date();while(true){const k=d.toISOString().slice(0,10);if(S.daily[k]?.completed||S.tasks[k]){n++;d.setDate(d.getDate()-1)}else break}return n}
function renderDaily(){const d=today(),text=ALL[(Array.from(d).reduce((a,c)=>a+c.charCodeAt(0),0))%ALL.length],done=S.daily[d]?.completed;return `${header('Günlük Çalışma','Bugünün kısa C-Test’i','Her gün aynı tarih için aynı alıştırma seçilir; ilerlemen yalnızca bu cihazda tutulur.')}<section class="card"><div class="exercise-head"><div><span class="pill">${text.level} · ${esc(text.topic)}</span><h2>${esc(text.title)}</h2><p class="lead" style="font-size:14px;margin:0">20 boşluk · günlük seri: ${streak()} gün</p></div>${done?'<span class="success">✓ Bugün tamamlandı</span>':'<button class="button" id="dailyStart">Günlük mücadeleyi başlat</button>'}</div></section><div class="section-heading"><h2>Etkinlik takvimi</h2><span>Son 35 gün</span></div><section class="card"><div class="calendar">${Array.from({length:35},(_,i)=>{let x=new Date();x.setDate(x.getDate()-34+i);let k=x.toISOString().slice(0,10),hit=S.daily[k]?.completed||S.tasks[k];return `<div class="day ${hit?'done':''}" title="${k}">${x.getDate()}</div>`}).join('')}</div></section>`}
function optionsLevels(){return LEVELS.map(x=>`<option>${x}</option>`).join('')}function topicOptions(){return `<option value="all">Tüm konular</option>${TOPICS.map(x=>`<option value="${esc(x[0])}">${esc(x[0])}</option>`).join('')}`}
function renderPractice(){return `${header('Pratik','Kendi ritminde boşlukları tamamla.','Pratik modunda çözümler gönderimden sonra görünür. Hoşgörülü değerlendirme ayarlardan değiştirilebilir.')}<div class="grid grid-2"><section class="card"><h2 style="margin-top:0">Hızlı pratik</h2><form id="practiceForm"><div class="form-row"><label>Seviye</label><select name="level"><option value="mixed">Karışık (A1–C1)</option>${optionsLevels()}</select></div><div class="form-row"><label>Konu</label><select name="topic">${topicOptions()}</select></div><div class="form-row"><label>Boşluk sayısı</label><div class="choice-row">${[10,15,20].map(n=>`<button type="button" class="chip ${n===S.settings.gaps?'selected':''}" data-gaps="${n}">${n} boşluk</button>`).join('')}</div></div><label class="toggle"><input name="timer" type="checkbox" ${S.settings.timer?'checked':''}> Süre tut</label><div style="margin-top:20px"><button class="button">Pratiği başlat</button></div></form></section><section class="card"><h2 style="margin-top:0">Karışık ve uyarlanabilir pratik</h2><p class="lead" style="font-size:14px">Uyarlanabilir seçim, sık hata yapılan kategori ve daha önce çözülmemiş metinlere öncelik verir.</p><div class="form-row"><label>Metin sayısı</label><select id="mixedCount"><option value="2">2 metin</option><option value="3">3 metin</option><option value="5">5 metin</option></select></div><button class="button-outline" id="mixedStart">Karışık set başlat</button><button class="button-outline" id="adaptiveStart" style="margin-left:8px">Uyarlanabilir başlat</button><hr style="border:0;border-top:1px solid var(--line);margin:23px 0"><h3>Seviye pratiği</h3><div class="choice-row">${LEVELS.map(x=>`<button class="chip level-start" data-level="${x}">${x}</button>`).join('')}</div></section></div>`}
function startPractice(text,{gaps=S.settings.gaps,timer=false,daily=false,custom=false}={}){const generated=ctest(text.text,{gaps,hint:S.settings.hint,shortWords:S.settings.shortWords});if(!generated.gapCount){toast('Bu metinde yeterli uygun kelime yok.');return}window.ACTIVE={mode:'practice',text,generated,answers:Array(generated.gapCount).fill(''),started:Date.now(),timer:timer?Math.max(60,generated.gapCount*25):0,daily,custom};renderExercise()}
function renderExercise(){const a=window.ACTIVE,g=a.generated;document.querySelector('#main').innerHTML=`<div class="sticky"><div class="card"><div class="exercise-head"><div><span class="pill">${a.text.level} · ${esc(a.text.topic)}</span><h2 style="margin:7px 0 0">${esc(a.text.title)}</h2></div>${a.timer?`<span class="timer" id="timer">${clock(a.timer)}</span>`:'<span class="pill">Serbest çalışma</span>'}</div><div class="progressbar"><i id="answerProgress" style="width:0"></i></div><small class="label" id="answerCount">0 / ${g.gapCount} boşluk yanıtlandı</small></div></div><section class="card" style="margin-top:17px"><article class="ctext" id="exerciseText">${g.html}</article><div class="exercise-actions"><span class="label">İpucu: Tab veya Enter ile sonraki boşluğa geç.</span><button class="button" id="submitPractice">Cevapları kontrol et</button></div></section>`;wireGaps(a);if(a.timer)beginTimer()}
function clock(s){return `${String(Math.floor(s/60)).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`}
function wireGaps(a){const inputs=[...document.querySelectorAll('.gap')];inputs.forEach((el,i)=>{el.value=a.answers[i]||'';el.addEventListener('input',()=>{a.answers[i]=el.value;updateAnswerProgress(a);if(S.settings.autoNext&&el.value.length>=a.generated.items[i].missing.length&&inputs[i+1])inputs[i+1].focus()});el.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();(inputs[i+1]||document.querySelector('#submitPractice')).focus()}});el.addEventListener('focus',()=>setTimeout(()=>el.scrollIntoView({block:'center',behavior:'smooth'}),50));});updateAnswerProgress(a)}
function updateAnswerProgress(a){const n=a.answers.filter(Boolean).length,p=document.querySelector('#answerProgress'),c=document.querySelector('#answerCount');if(p)p.style.width=`${n/a.generated.gapCount*100}%`;if(c)c.textContent=`${n} / ${a.generated.gapCount} boşluk yanıtlandı`}
let interval;function beginTimer(){clearInterval(interval);interval=setInterval(()=>{const a=window.ACTIVE;if(!a)return clearInterval(interval);a.timer--;const t=document.querySelector('#timer');if(t)t.textContent=clock(a.timer);if(a.timer<=0){clearInterval(interval);toast('Süre doldu; cevaplar kontrol ediliyor.');submitPractice()}},1000)}
function submitPractice(){const a=window.ACTIVE;if(!a)return;clearInterval(interval);const result=score(a.generated.items,a.answers,{lenient:S.settings.lenient,acceptSS:S.settings.acceptSS});storeResult(a,result);renderResult(a,result)}
function storeResult(a,r){const elapsed=Math.max(1,Math.round((Date.now()-a.started)/1000)),record={id:uid(),date:today(),mode:a.mode,level:a.text.level,topic:a.text.topic,title:a.text.title,correct:r.correct,total:r.total,percent:r.percent,time:elapsed};S.attempts.push(record);r.details.filter(x=>!x.correct).forEach(x=>S.errors.push({id:uid(),date:today(),text:a.text.title,level:a.text.level,topic:a.text.topic,word:x.word,prefix:x.prefix,missing:x.missing,answer:x.answer,context:sentenceFor(a.text.text,x.word),category:category(x),mastery:0}));S.seen.push(a.text.id);if(a.daily)S.daily[today()]={completed:true,result:r.percent};save()}
function examTexts(){const used=new Set(S.seen.slice(-15));const pick=(levels,n)=>{let a=levels.flatMap(l=>DB[l]).filter(x=>!used.has(x.id));if(!a.length)a=levels.flatMap(l=>DB[l]);let x=a[(Date.now()+n*99)%a.length];used.add(x.id);return x};return [pick(['A1','A2'],0),pick(['A2','B1'],1),pick(['B1'],2),pick(['B2'],3),pick(['B2','C1'],4)]}
function newExam(){const texts=examTexts(),sets=texts.map(t=>({text:t,generated:ctest(t.text,{gaps:20}),answers:[]}));sets.forEach(s=>s.answers=Array(s.generated.gapCount).fill(''));S.activeExam={id:uid(),started:Date.now(),remaining:EXAM_SECONDS,current:0,sets,alerts:[]};save();renderExam()}
function renderExam(){const e=S.activeExam;if(!e)return renderExamStart();const set=e.sets[e.current],answered=set.answers.filter(Boolean).length,total=e.sets.reduce((n,s)=>n+s.generated.gapCount,0),done=e.sets.reduce((n,s)=>n+s.answers.filter(Boolean).length,0);document.querySelector('#main').innerHTML=`${header('Tam Deneme','40 dakikalık karışık C-Test','Beş metin kolaydan zora ilerler. Gönderdikten sonra yanıtlar kilitlenir.')}<div class="sticky"><section class="card"><div class="exercise-head"><div><span class="pill">Metin ${e.current+1} / 5 · ${set.text.level} · ${esc(set.text.topic)}</span><div class="exam-tabs">${e.sets.map((s,i)=>`<button class="exam-tab ${i===e.current?'active':''} ${s.answers.some(Boolean)?'complete':''}" data-exam-tab="${i}">${i+1}</button>`).join('')}</div></div><div><span class="timer" id="examTimer">${clock(e.remaining)}</span><br><small class="label">${done}/${total} yanıt</small></div></div><div class="progressbar"><i style="width:${done/total*100}%"></i></div></section></div><section class="card" style="margin-top:17px"><h2 style="margin-top:0">${esc(set.text.title)}</h2><article class="ctext" id="examText">${set.generated.html}</article><div class="exercise-actions"><button class="button-outline" id="examPrev" ${e.current===0?'disabled':''}>← Önceki</button><span class="label">Bu metin: ${answered}/${set.generated.gapCount}</span>${e.current===4?'<button class="button" id="endExam">Denemeyi bitir</button>':'<button class="button" id="examNext">Sonraki →</button>'}</div></section>`;wireExamGaps();startExamTimer()}
function renderExamStart(){document.querySelector('#main').innerHTML=`${header('Tam Deneme','Sınav simülasyonu','Yaklaşık 100 boşluk, beş artan zorlukta metin ve 40 dakika. Resmî FAU puan eşiği değildir.')}<div class="grid grid-2"><section class="card"><span class="pill">40 dakika · 5 metin</span><h2>Gerçekçi karışık akış</h2><ol style="line-height:2"><li>A1–A2</li><li>A2–B1</li><li>B1–B1.2</li><li>B2</li><li>B2–C1</li></ol><button class="button" id="startExam">Yeni tam deneme başlat</button></section><section class="card"><h3 style="margin-top:0">Kurallar</h3><p class="lead" style="font-size:14px">Yazım tam olarak değerlendirilir. İpucu ve çözüm deneme bitmeden gösterilmez. Sayfa yenilense bile açık deneme geri yüklenir.</p><div class="warning">10, 5 ve 1 dakika kala uyarı verilir. Süre biterse deneme otomatik gönderilir.</div></section></div>`}
function wireExamGaps(){const e=S.activeExam,set=e.sets[e.current],inputs=[...document.querySelectorAll('.gap')];inputs.forEach((el,i)=>{el.value=set.answers[i]||'';el.addEventListener('input',()=>{set.answers[i]=el.value;save();if(S.settings.autoNext&&el.value.length>=set.generated.items[i].missing.length&&inputs[i+1])inputs[i+1].focus()});el.addEventListener('keydown',ev=>{if(ev.key==='Enter'){ev.preventDefault();(inputs[i+1]||document.querySelector('#examNext')||document.querySelector('#endExam')).focus()}});el.addEventListener('focus',()=>setTimeout(()=>el.scrollIntoView({block:'center',behavior:'smooth'}),50));})}
function startExamTimer(){clearInterval(interval);interval=setInterval(()=>{let e=S.activeExam;if(!e)return clearInterval(interval);e.remaining--;const t=document.querySelector('#examTimer');if(t)t.textContent=clock(e.remaining);[600,300,60].forEach(n=>{if(e.remaining===n&&!e.alerts.includes(n)){e.alerts.push(n);toast(`${n/60} dakika kaldı.`)}});if(e.remaining%5===0)save();if(e.remaining<=0){clearInterval(interval);toast('Süre bitti; deneme gönderiliyor.');submitExam()}},1000)}
function submitExam(){const e=S.activeExam;if(!e)return;clearInterval(interval);const details=e.sets.flatMap(set=>score(set.generated.items,set.answers,{lenient:false,acceptSS:false}).details.map(x=>({...x,text:set.text}))),total=details.length,correct=details.filter(x=>x.correct).length,unanswered=details.filter(x=>!x.answer).length,percent=Math.round(correct/total*100),elapsed=EXAM_SECONDS-e.remaining;S.attempts.push({id:e.id,date:today(),mode:'exam',level:'Karışık',topic:'Karışık',title:'Tam deneme',correct,total,percent,time:elapsed,textScores:e.sets.map(set=>{const x=score(set.generated.items,set.answers,{lenient:false});return{title:set.text.title,level:set.text.level,percent:x.percent,correct:x.correct,total:x.total}})});details.filter(x=>!x.correct).forEach(x=>S.errors.push({id:uid(),date:today(),text:x.text.title,level:x.text.level,topic:x.text.topic,word:x.word,prefix:x.prefix,missing:x.missing,answer:x.answer,context:sentenceFor(x.text.text,x.word),category:category(x),mastery:0}));S.seen.push(...e.sets.map(x=>x.text.id));S.activeExam=null;save();if(window.__STANDALONE__)download(`LueckenSprint_deneme_yedegi_${today()}.json`,'application/json',JSON.stringify(S,null,2));renderExamResult({details,total,correct,unanswered,percent,elapsed})}
function renderExamResult(r){const band=r.percent<60?'Belirgin gelişim gerekli':r.percent<70?'Gelişiyor':r.percent<80?'Hedefe yaklaşıyor':r.percent<90?'Güçlü hedef performansı':'Çok güçlü performans';document.querySelector('#main').innerHTML=`${header('Tam Deneme','Deneme tamamlandı',`Eğitim tahmini: ${band}.`)}<section class="card"><div class="result-row"><div><small>Doğru</small><b>${r.correct}</b></div><div><small>Yanlış</small><b>${r.total-r.correct-r.unanswered}</b></div><div><small>Boş</small><b>${r.unanswered}</b></div><div><small>Toplam</small><b>${r.percent}%</b></div></div><div class="warning">Bu seviye tahmini FAU’nun resmî yerleştirme sonucu değildir. Yüzdeler yalnızca antrenman geri bildirimi sağlar.</div><h3>Metinlere göre sonuç</h3><div class="table-wrap"><table class="data-table"><tr><th>Metin</th><th>Seviye</th><th>Doğru</th><th>Sonuç</th></tr>${S.attempts.at(-1).textScores.map(x=>`<tr><td>${esc(x.title)}</td><td>${x.level}</td><td>${x.correct}/${x.total}</td><td>${x.percent}%</td></tr>`).join('')}</table></div><div class="exercise-actions"><button class="button-outline" data-go="errors">Hataları tekrar et</button><button class="button" data-go="exam">Yeni deneme</button></div></section>`}
function renderErrors(){const errs=S.errors.filter(x=>x.mastery<3).slice().reverse();return `${header('Hata Tekrarı','Zorlandığın boşlukları güçlendir.','Bir kelimeyi üç doğru tekrardan sonra ustalaşmış kabul ederiz.')}<section class="card">${errs.length?`<p class="lead" style="font-size:14px">${errs.length} aktif hata kaydı. Yanıtı eksik kısmıyla yaz.</p>${errs.map(e=>`<div class="mistake"><span class="pill">${esc(e.level)} · ${esc(e.category)}</span><p style="margin:10px 0">${esc(e.context.replace(e.word,e.prefix+'_____'))}</p><b>${esc(e.prefix)}</b><input class="gap review-input" data-error="${esc(e.id)}" aria-label="Eksik kısmı tamamla"><button class="button-outline check-error" data-error="${esc(e.id)}">Bu hatayı tekrar çalış</button><small class="label" style="margin-left:8px">Ustalık: ${e.mastery}/3</small></div>`).join('')}`:'<div class="empty">Aktif hata yok. Harika! Yeni pratikte oluşan hatalar burada görünür.</div>'}</section>`}
function checkError(id){const e=S.errors.find(x=>x.id===id),inp=document.querySelector(`.review-input[data-error="${id}"]`);if(!e||!inp)return;const ok=norm(inp.value,{lenient:true,acceptSS:S.settings.acceptSS})===norm(e.missing,{lenient:true,acceptSS:S.settings.acceptSS});if(ok){e.mastery++;inp.classList.add('correct');toast(e.mastery>=3?'Bu hata ustalaşıldı!':'Doğru! Bir tekrar daha kaydedildi.')}else{e.mastery=0;inp.classList.add('wrong');toast(`Doğru cevap: ${e.missing}`)}save();setTimeout(render,600)}
function renderCustom(){const saved=S.custom||[];return `${header('Kendi Metnim','Kendi özgün metninden C-Test üret.','Metni tarayıcında saklayabilir, düzenleyebilir veya silebilirsin.')}<div class="grid grid-2"><section class="card"><form id="customForm"><div class="form-row"><label>Başlık</label><input name="title" required placeholder="Örn. Mein Studienalltag"></div><div class="grid grid-2"><div class="form-row"><label>Seviye</label><select name="level">${optionsLevels()}</select></div><div class="form-row"><label>Konu</label><input name="topic" value="Kendi metnim"></div></div><div class="form-row"><label>Almanca metin</label><textarea name="text" required placeholder="İlk cümle tam kalır. Sonraki cümlelerde boşluklar otomatik üretilir."></textarea></div><div class="grid grid-2"><div class="form-row"><label>Boşluklar</label><select name="gaps"><option>10</option><option>15</option><option selected>20</option><option>25</option></select></div><div class="form-row"><label>Aralık</label><select name="every"><option value="2">Her ikinci uygun kelime</option><option value="3">Her üçüncü uygun kelime</option></select></div></div><button class="button" name="action" value="start">Önizle ve çalış</button><button class="button-outline" name="action" value="save" style="margin-left:8px">Yerel olarak kaydet</button></form></section><section class="card"><h2 style="margin-top:0">Kayıtlı metinler</h2>${saved.length?saved.map(x=>`<div class="mistake"><b>${esc(x.title)}</b> <span class="pill">${x.level}</span><br><small class="label">${esc(x.topic)} · ${x.text.split(/\s+/).length} kelime</small><div style="margin-top:9px"><button class="chip use-custom" data-id="${x.id}">Çalış</button><button class="chip delete-custom" data-id="${x.id}">Sil</button></div></div>`).join(''):'<div class="empty">Henüz kayıtlı özel metin yok.</div>'}</section></div>`}
function renderStats(){const a=S.attempts,byLevel=LEVELS.map(l=>{const x=a.filter(q=>q.level===l);let n=x.reduce((z,q)=>z+q.total,0),ok=x.reduce((z,q)=>z+q.correct,0);return{l,p:n?Math.round(ok/n*100):0,n}}),byTopic={};a.forEach(x=>{if(!byTopic[x.topic])byTopic[x.topic]=[0,0];byTopic[x.topic][0]+=x.correct;byTopic[x.topic][1]+=x.total});const weak=[...S.errors].filter(x=>x.mastery<3).reduce((o,x)=>(o[x.category]=(o[x.category]||0)+1,o),{}),s=attemptStats();return `${header('İstatistikler','İlerlemeni görünür kıl.','Yalnızca bu cihazdaki alıştırmalar hesaplanır.')}<div class="grid grid-3">${metric('Genel doğruluk',s.accuracy+'%')}${metric('En güçlü seviye',byLevel.filter(x=>x.n).sort((a,b)=>b.p-a.p)[0]?.l||'—')}${metric('Aktif hata',S.errors.filter(x=>x.mastery<3).length)}</div><div class="grid grid-2" style="margin-top:18px"><section class="card"><h3 style="margin-top:0">Seviyeye göre doğruluk</h3>${byLevel.map(x=>`<div style="margin:13px 0"><div style="display:flex;justify-content:space-between;font-size:13px"><b>${x.l}</b><span>${x.n?x.p+'%':'Henüz veri yok'}</span></div><div class="progressbar"><i style="width:${x.p}%"></i></div></div>`).join('')}</section><section class="card"><h3 style="margin-top:0">Zayıf alanlar</h3>${Object.keys(weak).length?Object.entries(weak).sort((a,b)=>b[1]-a[1]).map(([k,v])=>`<div class="mistake"><b>${esc(k)}</b><span style="float:right">${v} hata</span></div>`).join(''):'<div class="empty">Hata verisi oluştuğunda kategoriler burada görünür.</div>'}</section></div><div class="grid grid-2" style="margin-top:18px"><section class="card"><h3 style="margin-top:0">Haftalık etkinlik</h3><div class="bar-chart">${Array.from({length:7},(_,i)=>{let d=new Date();d.setDate(d.getDate()-6+i);let k=d.toISOString().slice(0,10),n=a.filter(x=>x.date===k).reduce((z,x)=>z+x.total,0);return `<div class="bar" style="height:${Math.max(7,Math.min(100,n/S.settings.dailyTarget*100))}%" title="${n} boşluk"><span>${d.getDate()}</span></div>`}).join('')}</div></section><section class="card"><h3 style="margin-top:0">Konu performansı</h3>${Object.keys(byTopic).length?Object.entries(byTopic).map(([k,[ok,n]])=>`<div class="mistake">${esc(k)}<span style="float:right">${Math.round(ok/n*100)}%</span></div>`).join(''):'<div class="empty">Bir alıştırma tamamla; konu dağılımı burada yer alır.</div>'}</section></div>`}
function renderSettings(){const z=S.settings;return `${header('Ayarlar','Çalışmanı sana uyarla.','Tüm tercihler ve ilerleme yalnızca tarayıcının yerel depolamasında tutulur.')}<div class="grid grid-2"><section class="card"><form id="settingsForm"><div class="form-row"><label>Tema</label><select name="theme">${['system','light','dark'].map(x=>`<option value="${x}" ${z.theme===x?'selected':''}>${x==='system'?'Sistem':x==='light'?'Açık':'Koyu'}</option>`).join('')}</select></div><div class="form-row"><label>Yazı boyutu</label><input name="font" type="range" min="14" max="20" value="${z.font}"><small class="label">${z.font}px</small></div><div class="form-row"><label>Günlük hedef (boşluk)</label><input name="dailyTarget" type="number" min="10" max="200" value="${z.dailyTarget}"></div>${[['lenient','Pratikte büyük/küçük harfi hoşgör'],['acceptSS','Pratikte ß yerine ss kabul et'],['hint','İlk harf ipucunu göster'],['timer','Pratikte süreyi varsayılan aç'],['autoNext','Sonraki boşluğa otomatik geç'],['instantSave','Yanıtları hemen kaydet'],['confirmExam','Denemeyi bitirmeden onay iste']].map(([k,l])=>`<label class="toggle" style="margin:12px 0"><input type="checkbox" name="${k}" ${z[k]?'checked':''}> ${l}</label>`).join('')}<button class="button" style="margin-top:16px">Ayarları kaydet</button></form></section><section class="card"><h2 style="margin-top:0">Yedekleme ve aktarım</h2><p class="lead" style="font-size:14px">İlerlemeyi cihazlar arasında taşımak için JSON yedeğini dışa aktarıp diğer cihazda içe aktar.</p><div class="choice-row"><button class="button-outline" id="exportJson">İlerlemeyi JSON indir</button><button class="button-outline" id="exportErrors">Hataları CSV indir</button><button class="button-outline" id="exportExams">Denemeleri CSV indir</button></div><div class="form-row" style="margin-top:20px"><label>JSON yedeğini içe aktar</label><input id="importJson" type="file" accept="application/json,.json"></div><div class="warning">İçe aktarma mevcut verinin üzerine yazmaz; kayıtları birleştirir. Geçersiz dosyalar reddedilir.</div><hr style="border:0;border-top:1px solid var(--line);margin:23px 0"><button class="button-danger" id="resetData">Tüm yerel ilerlemeyi sıfırla</button></section></div>`}
function download(name,type,data){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([data],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),500)}
function csv(rows){return rows.map(r=>r.map(v=>`"${String(v??'').replaceAll('"','""')}"`).join(',')).join('\n')}
function mergeImport(x){if(!x||typeof x!=='object'||!x.version||!Array.isArray(x.attempts)||!Array.isArray(x.errors))throw new Error('Bu geçerli bir LückenSprint yedeği değil.');const ids=new Set(S.attempts.map(a=>a.id));S.attempts.push(...x.attempts.filter(a=>a&&a.id&&!ids.has(a.id)));const errIds=new Set(S.errors.map(a=>a.id));S.errors.push(...x.errors.filter(a=>a&&a.id&&!errIds.has(a.id)));S.custom.push(...(x.custom||[]).filter(a=>a&&a.id&&!S.custom.some(b=>b.id===a.id)));S.daily={...S.daily,...(x.daily||{})};S.tasks={...S.tasks,...(x.tasks||{})};save()}
function render(){clearInterval(interval);const view=window.VIEW||'home',f={home:renderHome,daily:renderDaily,practice:renderPractice,exam:renderExam,errors:renderErrors,custom:renderCustom,stats:renderStats,settings:renderSettings}[view];document.querySelectorAll('.nav-btn').forEach(x=>x.classList.toggle('active',x.dataset.view===view));document.querySelector('#main').innerHTML=f?f():renderHome();bindView();window.LueckenSync?.mountSettingsPanel?.()}
