renderExamResult=function(r){const latest=S.attempts.at(-1);const rows=(latest?.textScores||[]).map(x=>`<tr><td>${esc(x.title)}</td><td>${x.level}</td><td>${x.correct}/${x.total}</td><td>${x.percent}%</td></tr>`).join('');document.querySelector('#main').innerHTML=`<div class="eyebrow">Tam Deneme</div><h1 class="page-title">Deneme tamamlandı</h1><p class="lead">Eğitim tahmini: ${trainingBand(r.percent)}.</p><section class="card"><div class="result-row"><div><small>Doğru</small><b>${r.correct}</b></div><div><small>Yanlış</small><b>${r.total-r.correct-r.unanswered}</b></div><div><small>Boş</small><b>${r.unanswered}</b></div><div><small>Toplam</small><b>${r.percent}%</b></div></div><div class="warning">Bu seviye tahmini FAU’nun resmî yerleştirme sonucu değildir. Ayarlardaki eğitim bantları kullanılmıştır.</div><div class="table-wrap"><table class="data-table"><tr><th>Metin</th><th>Seviye</th><th>Doğru</th><th>Sonuç</th></tr>${rows}</table></div><div class="exercise-actions"><button class="button-outline" data-go="errors">Hataları tekrar et</button><button class="button" data-go="exam">Yeni deneme</button></div></section>`;bindView()}
