function sentenceFor(text,word){return text.split(/(?<=[.!?])\s+/u).find(s=>s.includes(word))||text}
function renderResult(a,r){const avg=Math.round(Math.max(1,(Date.now()-a.started)/1000)/r.total);document.querySelector('#main').innerHTML=`${header('Sonuç','Pratik değerlendirmesi',r.percent>=80?'Çok iyi — güçlü hedef performansı.':'Her yanlış, sonraki pratik için değerli bir işaret.')}
<section class="card"><div class="result-row"><div><small>Doğru</small><b>${r.correct}</b></div><div><small>Yanlış</small><b>${r.incorrect}</b></div><div><small>Boş</small><b>${r.unanswered}</b></div><div><small>Sonuç</small><b>${r.percent}%</b></div></div><p class="label">Süre: ${Math.round((Date.now()-a.started)/60)} dk · Boşluk başına ortalama: ${avg} sn</p><div class="warning">Bu seviye tahmini FAU’nun resmî yerleştirme sonucu değildir.</div><h3>Çözümler ve hata analizi</h3>${r.details.map(d=>`<div class="mistake"><b>${esc(d.prefix)}${esc(d.missing)}</b> ${d.correct?'✓':'— Senin cevabın: '+(esc(d.answer)||'boş')}<br><span class="label">${d.correct?'Doğru.':`Doğru eksik bölüm: <b>${esc(d.missing)}</b> · ${esc(sentenceFor(a.text.text,d.word))} · ${d.correct?'':'Kategori: '+category(d)}`}</span></div>`).join('')}<div class="exercise-actions"><button class="button-outline" data-go="errors">Bu hatayı tekrar çalış</button>${window.MIX&&window.MIX.index<window.MIX.list.length-1?'<button class="button" id="nextMixed">Sonraki metin</button>':'<button class="button" data-go="practice">Yeni pratik</button>'}</div></section>`;bindView();document.querySelector('#nextMixed')?.addEventListener('click',()=>{window.MIX.index++;startPractice(window.MIX.list[window.MIX.index],{gaps:S.settings.gaps,timer:S.settings.timer})})}
